import { readFileSync } from 'node:fs';
import { createIndex } from './resolve.js';

// Read as JSON (not `import ... with { type: 'json' }`) so it works in Node and Vite alike.
const manifest = JSON.parse(readFileSync(new URL('../data/terms.json', import.meta.url), 'utf8'));
createIndex(manifest); // throws on duplicates, bad slugs or alias collisions

/** Validated glossary term index, generated by `scripts/sync-glossary.mjs`. */
export const glossaryTerms = manifest;
